mapper.insert:
insert into Player ( player_id, team_id, name, nation, birthday, position ) values
( #{playerDto.playerId}, #{playerDto.teamDto.teamId}, #{playerDto.name}, #{playerDto.nation}, #{playerDto.birthDay}, #{playerDto.position} )
on DUPLICATE key update player_id = VALUES(player_id), team_id = VALUES(team_id), name = VALUES(name), nation = VALUES(nation), birthday = VALUES(birthday), position = VALUES(position);
